const fb = new FormBuilder();
const profile = fb.group({
  name: ['', Validators.required],
  city: 'Paris',
  username: ['ada', Validators.required],
});

profile.reset();
console.log(profile.value);

const name = new FormControl<string>('Ada');
name.setValue('Grace');
console.log(name.value);

import { FormControl, FormGroup, Validators } from '@angular/forms';

const profile = new FormGroup({
  name: new FormControl('', { nonNullable: true, validators: Validators.required }),
  email: new FormControl('', { nonNullable: true }),
});

profile.setValue({ name: 'Ada', email: 'ada@example.com' });
profile.patchValue({ name: 'Grace' });

console.log(profile.value);
console.log(profile.getRawValue());

